  const seen = new Set();
  for (let i = 0; i < args.length; i += 2) {
    const key = args[i];
    if (
      !["--expected-full", "--upstream-result"].includes(key) ||
      i + 1 >= args.length ||
      seen.has(key)
    )
      throw Error(`Invalid argument: ${key}`);
    seen.add(key);
    options[key === "--expected-full" ? "expectedFull" : "upstreamResult"] =
      args[i + 1];
  }
