import { mkdirSync, writeFileSync } from "node:fs";
import path from "node:path";
import { pathToFileURL } from "node:url";

// Report and lifecycle fixtures own real commands, receipts and retirement.
// Only unrelated host tool-version startup is replaced with a stable dependency.
export function toolVersionFixture(root, env) {
  const preload = path.join(root, "target/fixture-tool-versions.cjs");
  const probes = path.join(root, "target/fixture-tool-versions.log");
  mkdirSync(path.dirname(preload), { recursive: true });
  writeFileSync(preload, `
const cp = require('node:child_process');
const path = require('node:path');
const fs = require('node:fs');
const original = cp.spawnSync;
cp.spawnSync = function(program, args) {
  const name = path.basename(String(program)).replace(/\\.exe$/i, '');
  const direct = ['cargo', 'rustc', 'npm'].includes(name) && args?.length === 1 && args[0] === '--version';
  const npm = path.resolve(String(program)) === path.resolve(process.execPath) && args?.length === 2 && path.basename(args[0]) === 'npm-cli.js' && args[1] === '--version';
  if (!direct && !npm) return original.apply(this, arguments);
  const tool = npm ? 'npm' : name;
  fs.appendFileSync(process.env.MESH_FIXTURE_TOOL_VERSION_PROBES, tool + '\\n');
  const stdout = tool + ' validation-fixture\\n';
  return { status: 0, signal: null, stdout, stderr: '', output: [null, stdout, ''] };
};
require('node:module').syncBuiltinESMExports();
`);
  return {
    probes,
    env: { ...env,
      NODE_OPTIONS: `${env.NODE_OPTIONS || ""} --import=${pathToFileURL(preload).href}`.trim(),
      MESH_FIXTURE_TOOL_VERSION_PROBES: probes },
  };
}
});

test("command stream channels preserve structured stdout across stderr fragments", { timeout: 15000 }, async t => {
  const { runCommand } = await import("../pr-platform/guest.mjs");
  const root = await mkdtemp(path.join(os.tmpdir(), "mesh-owner-streams-"));
  t.after(() => rm(root, { recursive: true, force: true }));
  const logPath = path.join(root, "producer.log");
  const program = `
    const { readFile } = require('node:fs/promises');
    const { setImmediate } = require('node:timers/promises');
    const log = process.argv[1];
    async function visible(fragment) {
      while (true) {
        try { if ((await readFile(log)).includes(fragment)) return; }
        catch (error) { if (error.code !== 'ENOENT') throw error; }
        await setImmediate();
      }
    }
    (async () => {
      process.stderr.write('progress-prefix ');
      await visible(Buffer.from('progress-prefix '));
      process.stdout.write('{"reason":"build-finished","success":true,"text":"');
      process.stdout.write(Buffer.from([0xf0, 0x9f]));
      await visible(Buffer.from([0xf0, 0x9f]));
      process.stderr.write('progress-mid ');
      await visible(Buffer.from('progress-mid '));
      process.stdout.write(Buffer.from([0x98, 0x80]));
      process.stdout.write('"}\\n');
      await visible(Buffer.from('"}\\n'));
      process.stderr.write('progress-end\\n');
    })().catch(error => { console.error(error); process.exitCode = 1; });
  `;
  const result = await runCommand(process.execPath, ["-e", program, "--", logPath], { logPath, timeoutMs: 10000 });
  assert.equal(result.code, 0, result.error);
  assert.equal(result.cleanupUnverified, false);
  assert.equal(typeof result.stdout, "string");
  assert.equal(result.outputTruncated, false);
  assert.deepEqual(JSON.parse(result.stdout), { reason: "build-finished", success: true, text: "😀" });
  assert.equal(result.stderr, "progress-prefix progress-mid progress-end\n");
  assert.match(result.output, /progress-prefix/u);
  assert.match(result.output, /progress-mid/u);
});

