import assert from "node:assert/strict";
import { copyFileSync, mkdtempSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { pathToFileURL } from "node:url";
import { spawnSync } from "node:child_process";
import test from "node:test";

const root = () => readFileSync(new URL("../../.github/workflows/e2e-ui.yml", import.meta.url), "utf8");
const job = name => root().split(`  ${name}:\n`)[1]?.split(/^  [a-z][\w-]*:\n/m)[0];
function gate(name, env) {
  const block = root().split(/^      - /m).find(step => step.startsWith(`name: ${name}\n`));
  assert.ok(block, name);
  const script = block.split("        run: |\n")[1].replace(/^          /gm, "");
  return spawnSync("bash", ["-e", "-c", script], { encoding: "utf8", env: { ...process.env, ...env } }).status;
}

test("Linux coverage requires Linux and Health without waiting for desktop shards", () => {
  assert.match(job("coverage"), /needs: \[linux, health, scope\]/);
  assert.doesNotMatch(job("coverage"), /needs:.*desktop/);
  for (const linux of ["success", "failure", "cancelled", "skipped", ""]) {
    assert.equal(gate("Require all browser shards", { BASELINE: linux, UNIT_COVERAGE: "success", DESKTOP: "failure" }) === 0, linux === "success");
  }
});

test("portable acceptance and final UI gate reject every unsuccessful Linux or desktop result", () => {
  const env = { LINUX: "success", DESKTOP: "success", COVERAGE: "success", PACKS: "success", CHROMIUM: "success", PORTABLE: "success", EXTENDED_CHROMIUM: "skipped", FIREFOX: "success", EXTENDED: "false" };
  for (const name of ["portable-evidence", "reports"]) assert.match(job(name), /needs: \[linux, desktop, scope\]/);
  assert.match(job("portable-evidence"), /node scripts\/evals\/chromium-evidence\.mjs collect-artifacts/);
  assert.match(job("ui-gate"), /needs: \[linux, desktop,/);
  for (const linux of ["success", "failure", "cancelled", "skipped", ""]) {
    for (const desktop of ["success", "failure", "cancelled", "skipped", ""]) {
      const expected = linux === "success" && desktop === "success";
      assert.equal(gate("Require all full Chromium shards", { LINUX: linux, DESKTOP: desktop }) === 0, expected);
      assert.equal(gate("Require complete selected UI matrices", { ...env, LINUX: linux, DESKTOP: desktop }) === 0, expected);
    }
  }
});

test("one reusable shard implementation retains platform-sized runners and all evidence identities", () => {
  const reusable = readFileSync(new URL("../../.github/workflows/ui-shards.yml", import.meta.url), "utf8");
  assert.match(reusable, /operating_systems:\n        type: string\n        required: true/);
  assert.match(reusable, /os: \$\{\{ fromJSON\(inputs.operating_systems\) \}\}/);
  assert.match(reusable, /shard: \$\{\{ fromJSON\(inputs.shards\) \}\}/);
  assert.match(job("linux"), /operating_systems: '\["ubuntu-24.04"\]'/);
  assert.match(job("desktop"), /- os: macos-26-intel\n            shards: '\[1,2,3,4,5,6,7,8\]'\n            total: 8/);
  assert.match(job("desktop"), /- os: windows-latest\n            shards: '\[1,2,3,4\]'\n            total: 4/);
  assert.equal((root().match(/uses: \.\/\.github\/workflows\/ui-shards.yml/g) ?? []).length, 2);
  assert.ok(!root().includes("name: Run UI E2E"));
  assert.match(reusable, /node \.\.\/scripts\/ci\/ui-runner\.mjs --workers=1 --retries=0 --shard=\$\{\{ matrix.shard \}\}\/\$\{\{ inputs.shard_total \}\} --reporter=list,blob,json,\.\.\/scripts\/ci\/ui-runner\.mjs/);
  assert.match(reusable, /MESH_TALK_E2E_COVERAGE: \$\{\{ runner.os == 'Linux' && '1' \|\| '0' \}\}/);
  for (const prefix of ["playwright-ui", "chromium-portable"]) assert.ok(reusable.includes(`name: ${prefix}-`));
  assert.match(reusable, /SOURCE_SHA: \$\{\{ github.sha \}\}/);
  assert.match(reusable, /if: always\(\)/);
  assert.match(reusable, /if-no-files-found: error/);
});

test("browser job budget reserves cleanup before dependency work and persists interruption evidence", () => {
  const reusable = readFileSync(new URL("../../.github/workflows/ui-shards.yml", import.meta.url), "utf8");
  assert.match(reusable, /timeout_minutes:\n        type: number\n        default: 25/);
  assert.match(reusable, /timeout-minutes: \$\{\{ inputs.timeout_minutes \}\}/);
  assert.ok(reusable.indexOf("name: Reserve browser cleanup") < reusable.indexOf("name: Install dependencies"));
  assert.match(reusable, /frontend\/ui-runner-evidence\//);
  const block = reusable.split(/^      - /m).find(value => value.startsWith("name: Reserve browser cleanup and evidence time\n"));
  assert.match(block, /shell: bash/);
  const script = block.split("        run: |\n")[1].replace(/^          /gm, "");
  const directory = mkdtempSync(path.join(tmpdir(), "mesh-ui-budget-"));
  try {
    for (const minutes of ["25", "2", "invalid"]) {
      const envFile = path.join(directory, "environment");
      writeFileSync(envFile, "");
      const result = spawnSync("bash", ["-e", "-c", script], { cwd: directory, encoding: "utf8", env: { ...process.env, UI_JOB_MINUTES: minutes, GITHUB_ENV: envFile } });
      assert.equal(result.status === 0, minutes === "25", result.stderr);
      if (minutes === "25") {
        const budget = JSON.parse(readFileSync(path.join(directory, "ui-runner-evidence/budget.json"), "utf8"));
        assert.equal(budget.deadline - budget.startedAt, 23 * 60000);
        assert.equal(readFileSync(envFile, "utf8"), `MESH_UI_DEADLINE_MS=${budget.deadline}\n`);
      }
    }
  } finally { rmSync(directory, { recursive: true, force: true }); }
});

test("macOS browsers, Health and backend use Intel while Rust and native retain ARM", () => {
  const health = readFileSync(new URL("../../.github/workflows/check-health.yml", import.meta.url), "utf8");
  const rust = readFileSync(new URL("../../.github/workflows/ci.yml", import.meta.url), "utf8");
  const native = readFileSync(new URL("../../.github/workflows/hidden-contacts-native.yml", import.meta.url), "utf8");
  assert.match(job("desktop"), /- os: macos-26-intel\n            shards: '\[1,2,3,4,5,6,7,8\]'\n            total: 8/);
  assert.match(job("desktop"), /- os: windows-latest\n            shards: '\[1,2,3,4\]'\n            total: 4/);
  assert.match(job("portable-shards"), /runs-on: macos-26-intel/);
  assert.match(job("portable"), /name: Portable UI \(macos-26-intel, webkit\)/);
  assert.match(job("chromium-extended"), /os: \[ubuntu-24.04, macos-26-intel, windows-latest\]/);
  assert.match(job("portable-evidence"), /chromium-evidence.mjs collect-artifacts/);
  assert.match(job("reports"), /chromium-evidence.mjs render-artifacts/);
  assert.match(health, /os: \[ubuntu-latest, macos-26-intel, windows-latest\]/);
  assert.match(rust, /os: \[ubuntu-latest, macos-latest\]/);
  assert.match(native, /os: \[ubuntu-24.04, windows-2022, macos-latest\]/);
});

test("desktop browser burst waits for Health and WebKit with bounded admission while Linux starts independently", () => {
  const reusable = readFileSync(new URL("../../.github/workflows/ui-shards.yml", import.meta.url), "utf8");
  assert.match(job("desktop"), /needs: \[health, portable, scope\]/);
  assert.doesNotMatch(job("desktop"), /max_parallel:/, "desktop inherits the same four-slot owner without a Mac-specific Windows restriction");
  assert.match(reusable, /max_parallel:\n        type: number\n        default: 4/);
  assert.match(reusable, /max-parallel: \$\{\{ inputs.max_parallel \}\}/);
  assert.doesNotMatch(job("linux"), /max_parallel:/);
  assert.doesNotMatch(job("desktop"), /if: always\(\)/);
  assert.match(job("linux"), /needs: \[scope\]/);
});

test("HTML reports require all platform-specific current-attempt shards", () => {
import assert from "node:assert/strict";
import { readFileSync, readdirSync } from "node:fs";
import { readFile } from "node:fs/promises";
import test from "node:test";
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";
import { versions } from "../ci/windows-coverage.mjs";

// Also runs in cheap PR validation. Keep this owner limited to configuration
// assertions and test-inventory discovery; no suites, compilation or installs.

const read = name => readFileSync(new URL(`../../.github/workflows/${name}`, import.meta.url), "utf8");
const step = (source, name) => source.split(/^      - /m).find(value => value.startsWith(`name: ${name}\n`));

const workflowJob = (source, id) => source.split(`  ${id}:\n`)[1]?.split(/^  [a-z][\w-]*:\n/m)[0];

test("documentation scope retains every required matrix identity and guards expensive steps", () => {
  const required = {
    "ci.yml": ["checks"],
    "windows-workspace.yml": ["build", "tests"],
    "check-health.yml": ["platform", "source"],
    "e2e-backend.yml": ["backend-platform"],
    "hidden-contacts-native.yml": ["native"],
    "sanitizers.yml": ["asan"],
    "e2e-ui.yml": ["coverage", "portable-evidence", "portable", "ui-gate"],
  };
  for (const [file, ids] of Object.entries(required)) {
    const workflow = read(file);
    assert.doesNotMatch(workflow, /paths-ignore:/u, `${file}: required workflows remain discoverable`);
    for (const id of ids) {
      const block = workflowJob(workflow, id);
      assert.ok(block, `${file}/${id}`);
      assert.match(block, /if: \$\{\{ !cancelled\(\)/u, `${file}/${id}: reject failed selection rather than disappear`);
      const steps = block.split(/^      - /m).slice(1);
      assert.match(steps[0], /uses: actions\/checkout@/u);
      assert.match(steps[0], /fetch-depth: 2/u);
      assert.match(steps[1], /id: scope/u);
      assert.match(steps[1], /uses: \.\/\.github\/actions\/ci-scope/u);
      assert.match(steps[1], /upstream_result:/u);
      assert.doesNotMatch(steps[1], /continue-on-error/u);
      for (const work of steps.slice(2)) {
        const commonSource = file === "check-health.yml" && id === "source" && [
          "Install Rust", "Rust formatting", "Install source scanners",
          "Install pinned prebuilt workflow scanner", "Source and supply-chain policy",
        ].some(name => work.startsWith(`name: ${name}\n`));
        if (commonSource) {
          assert.doesNotMatch(work, /^        if:/mu, "portable source/security checks remain applicable to documentation");
          assert.doesNotMatch(work, /cargo (?:build|test|clippy)|npm run test|playwright/u);
          continue;
        }
        assert.match(work, /if: .*steps\.scope\.outputs\.full == '(?:true|false)'/u,
          `${file}/${id}: work after scope verification must explicitly select full or docs`);
      }
      if (/matrix\.os/u.test(block)) {
        assert.match(block, /runs-on: \$\{\{ .* == 'true' && matrix\.os \|\| 'ubuntu-latest' \}\}/u,
          `${file}/${id}: docs retain names without admitting native runners`);
      }
    }
  }
});

test("docs eligibility is recomputed locally and never fabricates provider or test evidence", () => {
  const selector = read("ci-scope.yml");
  assert.match(selector, /full: auto/u);
  const action = readFileSync(new URL("../../.github/actions/ci-scope/action.yml", import.meta.url), "utf8");
  assert.match(action, /scripts\/ci\/docs-scope\.mjs --expected-full "\$EXPECTED_FULL" --upstream-result "\$UPSTREAM_RESULT"/u);
  assert.match(action, /working-directory: \$\{\{ github.workspace \}\}/u);
  assert.doesNotMatch(action, /continue-on-error|checks: write|statuses: write|npm ci|rust-cache/u);
  const empty = step(read("ci.yml"), "Report documentation-only coverage through Codecov");
  assert.match(empty, /steps\.scope\.outputs\.full == 'false' && matrix\.os == 'ubuntu-latest'/u);
  assert.match(empty, /run_command: empty-upload/u);
  assert.match(empty, /version: v11\.3\.2/u);
  assert.match(empty, /fail_ci_if_error: true/u);
  assert.doesNotMatch(empty, /force:|skip_validation:|handle_no_reports_found:|dry_run:|override_commit:/u);
  const source = workflowJob(read("check-health.yml"), "source");
  for (const command of ["node scripts/validation/standards.mjs", "node scripts/check-repository-hygiene.mjs", "typos"]) {
    assert.ok(source.includes(command), `documentation validation retains ${command}`);
  }
  assert.match(read("codeql.yml"), /language: \[rust, javascript-typescript, actions\]/u);
  assert.doesNotMatch(read("codeql.yml"), /docs-scope|ci-scope|paths-ignore/u);
});

test("Codecov action and downloaded CLI versions are pinned independently", () => {
  let uploads = 0;
