    await delay(50);
    assert.ok(existsSync(executable));
    child.stdin.end();
    assert.equal(await removal, null);
    assert.equal(existsSync(directory), false);
    assert.equal((await exited)[0], 0);
  } finally {
    child?.kill();
    await exited?.catch(() => {});
    await removeCliFixture(directory);
  }
});
